#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
e=$(mktemp)
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh --room 2>"$e"); code=$?
[ "$code" = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without a value"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>"$e"); code=$?
[ "$code" = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date"; fail=1; }
for d in 2026-13-01 2026-01-32 2026-1-5; do
  out=$(BOOKINGS=$t bash src/list.sh "$d" 2>"$e"); code=$?
  [ "$code" = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = "bad date: $d (expected YYYY-MM-DD)" ] || { echo "list bad date $d"; fail=1; }
done
t2=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t13:00\t14:00\tz\n' > "$t2"
[ "$(BOOKINGS=$t2 bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 13:00-14:00 aoi z' ] || { echo "list --room with a date"; fail=1; }
rm -f "$t" "$t2" "$e"; exit $fail

